package ai.decisionos.aside;
import android.app.*;import android.widget.*;import org.json.*;import java.util.*;
/** Global, goal-filtered progress, saved material and schedule. */
final class NubiLibraryUi {
 final NubiCompanionUi ui;final GoalAgentActivity a;final GoalChatUi c;final NavigationState nav;int count;
 NubiLibraryUi(NubiCompanionUi ui){this.ui=ui;a=ui.a;c=ui.c;nav=new NavigationState(a);if(!nav.libraryGoal.isEmpty())try{a.store.goal(nav.libraryGoal);}catch(Exception e){nav.filter("",nav.libraryTab);}}
 boolean include(JSONObject row){String gid=row.optString("goalId");try{return !GoalStore.fixture(a.store.goal(gid))&&(nav.libraryGoal.isEmpty()||nav.libraryGoal.equals(gid));}catch(Exception e){return false;}}
 String owner(JSONObject row){try{JSONObject g=a.store.goal(row.optString("goalId"));return GoalRules.preset(g.optString("character")).name+" · "+g.optString("title");}catch(Exception e){return "이전 기록";}}
 void origin(JSONObject row){String gid=row.optString("goalId"),conversation=row.optString("conversationId");c.switchConversation(gid,conversation);}
 void show(){ui.sideBody.removeAllViews();ui.add(nav.libraryGoal.isEmpty()?"전체 목표":a.store.goal(nav.libraryGoal).optString("title"),"모든 누비의 기록을 한곳에서 확인해요.","필터",this::filter);LinearLayout tabs=new LinearLayout(a);for(String tab:new String[]{"진행","저장","일정"}){TextView button=ui.button(tab,()->{nav.filter(nav.libraryGoal,tab);show();});button.setTextColor(tab.equals(nav.libraryTab)?NubiCompanionUi.INK:NubiCompanionUi.MUTED);tabs.addView(button,new LinearLayout.LayoutParams(0,ui.dp(48),1));}ui.sideBody.addView(tabs);count=0;
 if(nav.libraryTab.equals("진행")){for(JSONObject run:a.store.workspace("runs",null))if(include(run)){count++;ui.add(run.optString("text",run.optString("text","이전 실행")),owner(run)+"\n"+CompanionCards.state(run.optString("state")),"대화 보기",()->origin(run));}ui.add("실제 탐색 화면","현재 기기에서 열린 브라우저","보기",ui::browser);}
 else if(nav.libraryTab.equals("저장")){Set<String> seen=new HashSet<>();for(JSONObject artifact:a.store.workspace("artifacts",null))if(include(artifact)){String key=artifact.optString("job_id")+artifact.optString("manifest");if(!seen.add(key))continue;JSONObject manifest=artifact.optJSONObject("manifest");JSONArray files=manifest==null?null:manifest.optJSONArray("files");for(int n=0;files!=null&&n<files.length();n++){JSONObject file=files.optJSONObject(n);if(file==null||!(file.optString("name").endsWith(".docx")||file.optString("name").endsWith(".hwpx")))continue;count++;ui.add(file.optString("name"),owner(artifact)+"\n"+CompanionCards.documentState(artifact),"문서 열기",()->c.openDocument(artifact,file));}}for(JSONObject goal:a.store.goals()){if(GoalStore.fixture(goal)||!nav.libraryGoal.isEmpty()&&!nav.libraryGoal.equals(goal.optString("id")))continue;for(JSONObject item:a.store.contents(goal.optString("id"),"",true)){count++;ui.add(item.optString("title"),owner(GoalStore.put(new JSONObject(),"goalId",goal.optString("id"))),"원문 보기",()->c.showSource(item.optString("url")));}}}
 else{ui.add("일정·할 일 관리","목표별 일정과 공통 할 일을 확인·추가해요.","관리",()->ui.select("할 일"));try(TaskStore tasks=new TaskStore(a)){try(android.database.Cursor rows=tasks.getReadableDatabase().rawQuery("SELECT title,due,goal_id,start_at,end_at,timezone,is_all_day FROM tasks ORDER BY due",null)){while(rows.moveToNext()){String gid=rows.getString(2);if(!nav.libraryGoal.isEmpty()&&!nav.libraryGoal.equals(gid))continue;count++;String time=rows.getInt(6)==1?rows.getString(1)+" · 종일":rows.getString(3)+" ~ "+rows.getString(4)+" · "+rows.getString(5);ui.add(rows.getString(0),time,"",null);}}}}
 if(count==0)ui.muted(nav.libraryTab.equals("진행")?"아직 실행 기록이 없어요. 목표 대화에서 원하는 일을 맡겨보세요.":nav.libraryTab.equals("저장")?"아직 저장한 자료가 없어요.":"아직 일정이 없어요.");}
 void filter(){List<String> names=new ArrayList<>(),ids=new ArrayList<>();names.add("전체 목표");ids.add("");for(JSONObject g:a.store.goals())if(!GoalStore.fixture(g)){names.add(GoalRules.preset(g.optString("character")).name+" · "+g.optString("title"));ids.add(g.optString("id"));}new AlertDialog.Builder(a).setTitle("목표 필터").setItems(names.toArray(new String[0]),(d,n)->{nav.filter(ids.get(n),nav.libraryTab);show();}).setNegativeButton("닫기",null).show();}
}
